mapper.select:
SELECT COUNT(*)
FROM attendance
WHERE member_id = #{memberId}
  AND attend_date = #{attendDate}

SELECT attend_date
FROM attendance
WHERE member_id = #{memberId}
  AND attend_date BETWEEN #{startDate} AND #{endDate}
ORDER BY attend_date

SELECT COUNT(*)
FROM attendance
WHERE member_id = #{memberId}
  AND attend_date >= #{sinceDate}
